/* Receipt header background (wave image) — first page and following pages */

/* ===== SF logo used in every downloaded receipt (cut from the brand header image) ===== */
const LOGO_SF_RATIO = 1.5606;

const RECEIPT_TEMPLATE = "data:image/jpeg;base64,";

/* Receipt page design: the SF letterhead template fills every page.
   The name goes in the middle pill, the date in the pill on the right
   (the template already has the logo and the calendar icon). */
function drawReceiptHeader(doc, W, isFirst, titleText, today) {
  const H = doc.internal.pageSize.getHeight();
  const px = W / 1055;                           // template is 1055 x 1491 px
  const navy = [10, 62, 165];

  try { doc.addImage(RECEIPT_TEMPLATE, 'JPEG', 0, 0, W, H); }
  catch (e) { doc.setFillColor(225, 241, 255); doc.rect(0, 0, W, 34, 'F'); }

  // ---- name, centred in the middle pill (shrinks to fit) ----
  const nx = 352 * px, nw = (632 - 352) * px, cy = 125.5 * px;
  const maxW = nw - 6;
  let name = String(titleText || '');
  let fs = 12;
  doc.setFont('helvetica', 'bold'); doc.setFontSize(fs);
  while (doc.getTextWidth(name) > maxW && fs > 6.5) { fs -= 0.5; doc.setFontSize(fs); }
  while (doc.getTextWidth(name) > maxW && name.length > 4) name = name.slice(0, -2);
  if (name !== String(titleText || '')) name = name.trim() + '…';
  doc.setTextColor(navy[0], navy[1], navy[2]);
  doc.text(name, nx + nw / 2, cy + fs * 0.3528 * 0.34, { align: 'center' });

  // ---- date (small) with the time under it, in the right pill after the calendar icon ----
  const now = new Date();
  const dateTxt = now.toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });
  const timeTxt = now.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: true });
  const dx = 838 * px, dEnd = 1008 * px, dMax = dEnd - dx, dcx = dx + dMax / 2;
  let dfs = 7.5;
  doc.setFont('helvetica', 'bold'); doc.setFontSize(dfs);
  while (doc.getTextWidth(dateTxt) > dMax && dfs > 5) { dfs -= 0.5; doc.setFontSize(dfs); }
  doc.text(dateTxt, dcx, cy - 0.9, { align: 'center' });
  doc.setFont('helvetica', 'normal'); doc.setFontSize(dfs - 0.5);
  doc.text(timeTxt, dcx, cy + 2.7, { align: 'center' });

  doc.setTextColor(0, 0, 0);
}

/* ---- "Download" -> choose .pdf or Image (png) ---- */
function offerReceiptDownload(doc, baseName) {
  const old = document.getElementById('dlPickOverlay');
  if (old) old.remove();

  const ov = document.createElement('div');
  ov.id = 'dlPickOverlay';
  ov.className = 'dl-pick-overlay';
  ov.innerHTML =
    '<div class="dl-pick-card" role="dialog" aria-modal="true" aria-label="Download receipt">' +
      '<button type="button" class="dl-pick-x" aria-label="Cancel">&times;</button>' +
      '<h3 class="dl-pick-title">Download receipt</h3>' +
      '<div class="dl-pick-row">' +
        '<button type="button" class="dl-pick-btn dl-pick-pdf" data-fmt="pdf">' +
          '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8z"/><path d="M14 3v5h5"/><path d="M9 13h6M9 17h4"/></svg>' +
          '<b>.pdf</b></button>' +
        '<button type="button" class="dl-pick-btn dl-pick-img" data-fmt="png">' +
          '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="9" cy="9" r="1.8"/><path d="M21 15l-5-5L5 21"/></svg>' +
          '<b>Image</b></button>' +
      '</div>' +
      '<p class="dl-pick-msg" id="dlPickMsg"></p>' +
    '</div>';
  document.body.appendChild(ov);

  const close = () => ov.remove();
  ov.addEventListener('click', (e) => { if (e.target === ov) close(); });
  ov.querySelector('.dl-pick-x').addEventListener('click', close);

  ov.querySelectorAll('.dl-pick-btn').forEach(btn => {
    btn.addEventListener('click', async () => {
      if (btn.dataset.fmt === 'pdf') {
        doc.save(baseName + '.pdf');
        close();
        return;
      }
      // image (png)
      const msg = ov.querySelector('#dlPickMsg');
      ov.querySelectorAll('.dl-pick-btn').forEach(b => b.disabled = true);
      msg.textContent = 'Preparing image…';
      try {
        await downloadReceiptPng(doc, baseName);
        close();
      } catch (err) {
        console.error(err);
        msg.textContent = 'Image could not be created. Please check your internet and try again.';
        ov.querySelectorAll('.dl-pick-btn').forEach(b => b.disabled = false);
      }
    });
  });
}

let _pdfjsPromise = null;
function loadPdfJs() {
  if (window.pdfjsLib) return Promise.resolve(window.pdfjsLib);
  if (_pdfjsPromise) return _pdfjsPromise;
  const base = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/';
  _pdfjsPromise = new Promise((resolve, reject) => {
    const s = document.createElement('script');
    s.src = base + 'pdf.min.js';
    s.onload = () => {
      window.pdfjsLib.GlobalWorkerOptions.workerSrc = base + 'pdf.worker.min.js';
      resolve(window.pdfjsLib);
    };
    s.onerror = () => { _pdfjsPromise = null; reject(new Error('pdf.js failed to load')); };
    document.head.appendChild(s);
  });
  return _pdfjsPromise;
}

// Renders the receipt pages to one PNG (pages stacked top to bottom) and downloads it
async function downloadReceiptPng(doc, baseName) {
  const pdfjs = await loadPdfJs();
  const pdf = await pdfjs.getDocument({ data: doc.output('arraybuffer') }).promise;
  const scale = 2.5, gap = 0;
  const canvases = [];
  for (let i = 1; i <= pdf.numPages; i++) {
    const page = await pdf.getPage(i);
    const vp = page.getViewport({ scale });
    const c = document.createElement('canvas');
    c.width = Math.round(vp.width); c.height = Math.round(vp.height);
    const ctx = c.getContext('2d');
    ctx.fillStyle = '#ffffff'; ctx.fillRect(0, 0, c.width, c.height);
    await page.render({ canvasContext: ctx, viewport: vp }).promise;
    canvases.push(c);
  }
  const out = document.createElement('canvas');
  out.width = canvases[0].width;
  out.height = canvases.reduce((s, c) => s + c.height + gap, 0) - gap;
  const octx = out.getContext('2d');
  octx.fillStyle = '#ffffff'; octx.fillRect(0, 0, out.width, out.height);
  let yy = 0;
  canvases.forEach(c => { octx.drawImage(c, 0, yy); yy += c.height + gap; });

  const blob = await new Promise(res => out.toBlob(res, 'image/png'));
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = baseName + '.png';
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 4000);
}

