/* ============================================================
   AUTH (Firestore-backed — credentials + data live in the cloud,
   not on one device.)
   ============================================================ */
const SESSION_KEY = 'hostelAuthSession';   // 'true' when logged in (per-device session only)

let isSignupMode = false;

// Every account gets its own isolated data (records / own account / trash)
// so that a new account never shows another account's previous data.
// The account is identified by NAME + PASSWORD together, not name alone —
// so two people can share the same name (common in a hostel) as long as
// their passwords differ, each getting their own separate account.
let currentAccountKey = '';
function accountKeyFor(name, password) {
  return name.trim().toLowerCase() + '__' + password;
}
function accountDocRef(key) {
  return db.collection('accounts').doc(key);
}

function setAuthError(msg) {
  const el = document.getElementById('authError');
  el.textContent = msg || '';
  el.classList.toggle('show', !!msg);
  if (msg) {
    const card = document.getElementById('authCard');
    card.classList.remove('shake');
    void card.offsetWidth;            // restart the shake animation
    card.classList.add('shake');
  }
}

function refreshAuthScreenMode(animate) {
  const screen    = document.getElementById('authScreen');
  const btnEl     = document.getElementById('authSubmitBtn');
  const labelEl   = document.getElementById('authSubmitLabel');
  const confirmIn = document.getElementById('authPasswordConfirm');
  const confirmEy = document.querySelector('[data-target="authPasswordConfirm"]');
  const passIn    = document.getElementById('authPassword');
  const changed   = screen.classList.contains('mode-signup') !== isSignupMode;

  screen.classList.toggle('mode-signup', isSignupMode);
  screen.classList.toggle('mode-login', !isSignupMode);

  document.getElementById('authTitle').textContent    = isSignupMode ? 'Create Account' : 'Welcome Back';
  document.getElementById('authSubText').textContent  = isSignupMode ? 'Start your SpendFlow journey' : 'Login to continue';
  document.getElementById('authFootText').textContent = isSignupMode ? 'Keep Your Expenses Organized!' : 'Manage your Expenses easily!';
  labelEl.textContent = isSignupMode ? 'Sign Up' : 'Login';

  // hidden confirm field must not be reachable with the keyboard
  confirmIn.tabIndex = isSignupMode ? 0 : -1;
  confirmEy.tabIndex = isSignupMode ? 0 : -1;
  passIn.setAttribute('autocomplete', isSignupMode ? 'new-password' : 'current-password');

  if (animate && changed) {
    document.querySelectorAll('#authScreen [data-swap]').forEach(el => {
      el.classList.remove('swap-in');
      void el.offsetWidth;
      el.classList.add('swap-in');
    });
    const foot = document.querySelector('.auth-foot');
    foot.classList.remove('redraw');
    void foot.offsetWidth;
    foot.classList.add('redraw');
  }
}

function switchAuthMode(toSignup) {
  isSignupMode = toSignup;
  setAuthError('');
  refreshAuthScreenMode(true);
}

async function handleAuthSubmit() {
  setAuthError('');
  const name     = document.getElementById('authName').value.trim();
  const password = document.getElementById('authPassword').value;

  if (!name) { setAuthError('Please enter your name.'); return; }
  if (!password) { setAuthError('Please enter a password.'); return; }

  const btnEl = document.getElementById('authSubmitBtn');
  const key   = accountKeyFor(name, password);
  btnEl.disabled = true;
  btnEl.classList.add('is-loading');
  document.getElementById('authSubmitLabel').textContent = isSignupMode ? 'Creating...' : 'Logging in...';

  try {
    if (isSignupMode) {
      const confirm = document.getElementById('authPasswordConfirm').value;
      if (password.length < 4) { setAuthError('Password must be at least 4 characters.'); return; }
      if (password !== confirm) { setAuthError('Passwords do not match.'); return; }

      const existing = await accountDocRef(key).get();
      if (existing.exists) {
        setAuthError('Please Enter a strong name or password. And sign up again.');
        return;
      }

      await accountDocRef(key).set({
        name, password,
        hostelDebt: [], hostelTrash: [], myOwnDebt: [], myAdvanceDebt: [],
        myExtra1Debt: [], myExtra2Debt: []
      });

      currentAccountKey = key;
      records = []; trashItems = []; ownRecords = []; advanceRecords = [];
      loadExtraRecords({});
      trackEvent('sign_up', { method: 'name_password' });
      startSession(name);
      return;
    }

    // Login mode — same name+password from ANY device pulls the same account
    const snap = await accountDocRef(key).get();
    if (!snap.exists) { setAuthError('No account found with this name and password. Please create one.'); return; }
    const data = snap.data();

    currentAccountKey = key;
    records        = data.hostelDebt   || [];
    trashItems     = data.hostelTrash  || [];
    ownRecords     = data.myOwnDebt    || [];
    advanceRecords = data.myAdvanceDebt || [];
    loadExtraRecords(data);
    trackEvent('login', { method: 'name_password' });
    startSession(data.name || name);
  } catch (err) {
    console.error(err);
    setAuthError('Connection error — please check your internet and try again.');
  } finally {
    btnEl.disabled = false;
    btnEl.classList.remove('is-loading');
    refreshAuthScreenMode();
  }
}

function startSession(name) {
  sessionStorage.setItem(SESSION_KEY, 'true');
  sessionStorage.setItem('hostelAuthName', name);
  sessionStorage.setItem('hostelAuthKey', currentAccountKey);
  showApp(name);
}

function logout() {
  trackEvent('logout');
  sessionStorage.removeItem(SESSION_KEY);
  sessionStorage.removeItem('hostelAuthName');
  sessionStorage.removeItem('hostelAuthKey');
  document.getElementById('authName').value = '';
  document.getElementById('authPassword').value = '';
  document.getElementById('authPasswordConfirm').value = '';
  isSignupMode = false;
  setAuthError('');
  refreshAuthScreenMode();
  document.getElementById('appMain').style.display = 'none';
  document.getElementById('authScreen').style.display = 'flex';
}

function showApp(name) {
  document.getElementById('authScreen').style.display = 'none';
  document.getElementById('appMain').style.display = 'block';
  document.getElementById('loggedInName').textContent = name;
  currentFilter = null;
  ownCurrentFilter = null;
  resetExtraFilters();
  setHomeView('dashboard');      // after login the Dashboard shows first (all lists closed)
  document.querySelectorAll('.dsh-card.open, .dsh-panel.open').forEach(c => c.classList.remove('open'));
  document.querySelectorAll('.dsh-toggle').forEach(t => t.setAttribute('aria-expanded', 'false'));
  initApp();
  renderDashboard();
}

async function checkExistingSession() {
  const loggedIn = sessionStorage.getItem(SESSION_KEY) === 'true';
  const name     = sessionStorage.getItem('hostelAuthName');
  const key      = sessionStorage.getItem('hostelAuthKey');

  if (loggedIn && name && key) {
    try {
      const snap = await accountDocRef(key).get();
      if (snap.exists) {
        const data = snap.data();
        currentAccountKey = key;
        records        = data.hostelDebt   || [];
        trashItems     = data.hostelTrash  || [];
        ownRecords     = data.myOwnDebt    || [];
        advanceRecords = data.myAdvanceDebt || [];
        loadExtraRecords(data);
        showApp(data.name || name);
        return;
      }
    } catch (err) {
      console.error(err);
    }
  }

  isSignupMode = false; // always default to Login; user can switch to "Create an account"
  refreshAuthScreenMode();
}

