/* ---- Records table (respects currentFilter) ---- */
function renderTable() {
  const area   = document.getElementById('tableArea');
  const badge  = document.getElementById('countBadge');
  const bar    = document.getElementById('totalBar');
  const dlBtn  = document.getElementById('downloadAllBtn');
  const clearBtn = document.getElementById('clearFilterBtn');
  const titleEl = document.getElementById('recordsTitle');
  const totalLabelEl = document.getElementById('totalLabel');

  const visibleRecords = currentFilter
    ? records.filter(r => r.lender.trim().toLowerCase() === currentFilter.toLowerCase())
    : records;

  if (currentFilter) {
    titleEl.textContent = currentFilter + "'s Records";
    totalLabelEl.textContent = currentFilter + "'s Total";
    if (clearBtn) clearBtn.style.display = 'inline-block';
    dlBtn.textContent = 'Download ' + currentFilter + "'s Receipt";
    dlBtn.onclick = () => downloadStudentPDF(currentFilter);
  } else {
    titleEl.textContent = 'All Records';
    totalLabelEl.textContent = 'Total Debt';
    if (clearBtn) clearBtn.style.display = 'none';
    dlBtn.textContent = 'Download All Receipt';
    dlBtn.onclick = () => downloadAllPDF();
  }

  badge.textContent = visibleRecords.length + ' Records';

  if (visibleRecords.length === 0) {
    area.innerHTML = '<div class="empty-state">No records added yet.</div>';
    bar.style.display = 'none';
    dlBtn.style.display = 'none';
    return;
  }

  const total = visibleRecords.reduce((s, r) => s + (r.struck ? 0 : r.amount), 0);
  document.getElementById('totalAmount').textContent = 'Rs. ' + total.toLocaleString('en-PK');
  bar.style.display = 'flex';
  dlBtn.style.display = 'inline-block';

  let rows = '';
  visibleRecords.forEach((r, i) => {
    const serial = visibleRecords.length - i; // oldest record = 1
    rows += `<tr>
      <td class="td-muted">${serial}</td>
      <td class="td-bold">${esc(r.student)}</td>
      <td>${esc(r.lender)}</td>
      <td class="td-amount${r.struck ? ' struck-amount' : ''}">Rs. ${r.amount.toLocaleString('en-PK')}</td>
      <td class="td-reason" title="${esc(r.reason)}" onclick="this.classList.toggle('reason-expanded')">${esc(r.reason)}</td>
      <td class="td-muted" style="white-space:nowrap;">${r.date} &nbsp; ${r.time}</td>
      <td class="td-check"><input type="checkbox" class="strike-check" ${r.struck ? 'checked' : ''} onchange="toggleStrike(${r.id})" title="Mark as settled"/></td>
      <td><button class="btn-del" onclick="deleteRecord(${r.id})">Delete</button></td>
    </tr>`;
  });

  area.innerHTML = `<div class="table-wrap"><table>
    <thead><tr>
      <th>#</th><th>name</th><th>nextname</th>
      <th class="th-blue">Amount</th><th>Reason</th><th>Date / Time</th><th>Paid</th><th></th>
    </tr></thead>
    <tbody>${rows}</tbody>
  </table></div>`;
}

function toggleStrike(id) {
  const r = records.find(x => x.id === id);
  if (!r) return;
  r.struck = !r.struck;
  save();
  renderTable();
  renderStudentAccounts();
}

function resetForm() {
  // studentName and lenderName intentionally kept
  document.getElementById('amount').value = '';
  document.getElementById('reason').value = '';
  const now = new Date();
  document.getElementById('date').value = now.toISOString().split('T')[0];
  document.getElementById('time').value = now.toTimeString().slice(0, 5);
}

function showToast() {
  const t = document.getElementById('toast');
  t.classList.add('show');
  setTimeout(() => t.classList.remove('show'), 2400);
}

function wrapMultiline(doc, text, width) {
  const out = [];
  String(text == null ? '' : text).split(/\r\n|\r|\n/).forEach(line => {
    if (line === '') { out.push(''); return; }
    out.push(...doc.splitTextToSize(line, width));
  });
  return out.length ? out : [''];
}

function esc(s) {
  return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}

function escAttr(s) {
  return String(s).replace(/\\/g,'\\\\').replace(/'/g,"\\'");
}

/* ============================================================
   PDF GENERATION
   ============================================================ */

// Download all records (or the currently filtered set) as one PDF
function downloadAllPDF() {
  const list = currentFilter
    ? records.filter(r => r.lender.trim().toLowerCase() === currentFilter.toLowerCase())
    : records;
  const title = currentFilter ? currentFilter + "'s Debt Receipt" : 'Student Debt Receipt';
  const filePrefix = currentFilter ? currentFilter.replace(/\s+/g, '_') + '_Receipt' : 'Receipt_list_FM';
  buildPDF(list, title, filePrefix);
}

// Download a single student's records only, regardless of current filter
function downloadStudentPDF(studentName) {
  const list = records.filter(r => r.lender.trim().toLowerCase() === studentName.toLowerCase());
  if (list.length === 0) return;
  const title = studentName + "'s Debt Receipt";
  const filePrefix = studentName.replace(/\s+/g, '_') + '_Receipt';
  buildPDF(list, title, filePrefix);
}

function buildPDF(recordsList, titleText, filenamePrefix) {
  if (recordsList.length === 0) return;

  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit: 'mm', format: 'a4' });
  const W      = doc.internal.pageSize.getWidth();
  const H      = doc.internal.pageSize.getHeight();
  const margin = 14;
  const today  = new Date().toLocaleDateString('en-PK');
  const total  = recordsList.reduce((s, r) => s + (r.struck ? 0 : r.amount), 0);

  // Column definitions — reason gets remaining space
  // #, Borrower, Lender, Amount, Date/Time, Reason
  const cols = [
    { x: margin,      w: 10  },  // #
    { x: margin + 10, w: 38  },  // Borrower
    { x: margin + 48, w: 38  },  // Lender
    { x: margin + 86, w: 28  },  // Amount
    { x: margin + 114,w: 28  },  // Date/Time
    { x: margin + 142,w: W - margin - 142 - margin }  // Reason — full remaining width
  ];
  const headers = ['No.', 'Name', "Boy's Name", 'Amount', 'Date / Time', 'Reason'];

  // ---- Page header function (called on each new page) ----
  function pageHeader(isFirst) {
    drawReceiptHeader(doc, W, isFirst, titleText, today);
  }

  pageHeader(true);

  // ---- Summary box ----
  doc.setFillColor(255, 245, 245);
  doc.setDrawColor(200, 180, 180);
  doc.setLineWidth(0.4);
  doc.roundedRect(margin, 38, W - margin * 2, 12, 2, 2, 'FD');
  doc.setTextColor(80, 80, 80);
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(8);
  doc.text('Total Records: ' + recordsList.length, margin + 4, 46);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(0, 110, 182);
  doc.setFontSize(9);
  doc.text('Total Debt: Rs. ' + total.toLocaleString('en-PK'), W - margin - 4, 46, { align: 'right' });

  let y = 57;

  // ---- Draw table header row ----
  function drawTableHeader() {
    doc.setFillColor(235, 235, 235);
    doc.rect(margin, y, W - margin * 2, 8, 'F');
    doc.setDrawColor(170, 170, 170);
    doc.setLineWidth(0.3);
    doc.rect(margin, y, W - margin * 2, 8, 'S');
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(7.5);
    doc.setTextColor(60, 60, 60);
    headers.forEach((h, i) => doc.text(h, cols[i].x + 2, y + 5.5));
    y += 10;
  }

  drawTableHeader();

  // ---- Rows ---- (oldest first → serial 1,2,3,4...)
  const orderedRecords = [...recordsList].reverse();
  orderedRecords.forEach((r, idx) => {
    // Calculate row height based on wrapped reason text
    doc.setFontSize(7.5);
    const reasonLines = wrapMultiline(doc, r.reason, cols[5].w - 4);
    const rowH = Math.max(9, reasonLines.length * 4.5 + 3);

    // New page check
    if (y + rowH > H - 30) {
      // Footer on current page
      drawPageFooter();
      doc.addPage();
      pageHeader(false);
      y = 38;
      drawTableHeader();
    }

    // Row background
    const bg = idx % 2 === 0 ? [255, 255, 255] : [249, 249, 249];
    doc.setFillColor(...bg);
    doc.rect(margin, y, W - margin * 2, rowH, 'F');
    doc.setDrawColor(215, 215, 215);
    doc.setLineWidth(0.2);
    doc.line(margin, y + rowH, W - margin, y + rowH);

    const midY = y + rowH / 2 + 1.5;

    // #
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(7.5);
    doc.setTextColor(130, 130, 130);
    doc.text(String(idx + 1), cols[0].x + 2, midY);

    // Borrower
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(10);
    doc.setTextColor(26, 26, 26);
    doc.text(doc.splitTextToSize(r.student, cols[1].w - 4), cols[1].x + 2, midY);

    // Lender
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(10);
    doc.setTextColor(50, 50, 50);
    doc.text(doc.splitTextToSize(r.lender, cols[2].w - 4), cols[2].x + 2, midY);

    // Amount
    doc.setFont('helvetica', r.struck ? 'italic' : 'bold');
    doc.setFontSize(8);
    doc.setTextColor(0, 110, 182);
    const amountText = 'Rs. ' + r.amount.toLocaleString('en-PK');
    doc.text(amountText, cols[3].x + 2, midY);
    if (r.struck) {
      const tw = doc.getTextWidth(amountText);
      doc.setDrawColor(0, 0, 0);
      doc.setLineWidth(0.35);
      doc.line(cols[3].x + 2, midY - 1.3, cols[3].x + 2 + tw, midY - 1.3);
    }

    // Date / Time
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(7);
    doc.setTextColor(100, 100, 100);
    doc.text(r.date, cols[4].x + 2, y + rowH / 2 - 0.5);
    doc.text(r.time, cols[4].x + 2, y + rowH / 2 + 4);

    // Reason — fully wrapped, no truncation
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(9);
    doc.setTextColor(26, 26, 26);
    const reasonTopY = y + (rowH - reasonLines.length * 4.5) / 2 + 3;
    doc.text(reasonLines, cols[5].x + 2, reasonTopY);

    y += rowH;
  });

  drawPageFooter();
  trackEvent('file_download', { file_extension: 'pdf', section: 'receivables' });
  offerReceiptDownload(doc, filenamePrefix + '_' + today.replace(/\//g, '-'));

  function drawPageFooter() {
    doc.setTextColor(120, 130, 150);
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(7);
    doc.text('Copyright © 2026 FM Register — ' + today, W / 2, H - 9.8, { align: 'center' });
  }
}

/* ============================================================
   MY OWN ACCOUNT — money the logged-in user borrowed from others
   (kept in a separate localStorage key from the main records)
   ============================================================ */
function addOwnRecord() {
  const from    = document.getElementById('ownFromName').value.trim();
  const amount  = parseFloat(document.getElementById('ownAmount').value);
  const date    = document.getElementById('ownDate').value;
  const timeRaw = document.getElementById('ownTime').value;
  const time    = convertTo12hr(timeRaw);
  const reason  = document.getElementById('ownReason').value.trim();

  if (!from)   { alert('Plz enter who you borrowed from.'); return; }
  if (!amount || amount <= 0) { alert('Plz enter a valid amount.'); return; }
  if (!date)   { alert('Plz select a date.'); return; }
  if (!reason) { alert('Plz enter a reason.'); return; }

  ownRecords.unshift({ id: Date.now(), from, amount, date, time, reason });
  trackEvent('add_entry', { section: 'main' });
  saveOwn();
  renderOwnAccounts();
  renderOwnTable();
  resetOwnForm();
  showToast();
}

function saveOwn() {
  if (!currentAccountKey) return;
  accountDocRef(currentAccountKey).set({ myOwnDebt: ownRecords }, { merge: true })
    .catch(err => console.error('Save failed:', err));
}

function deleteOwnRecord(id) {
  if (!confirm('Move this record to Trash?')) return;
  const r = ownRecords.find(x => x.id === id);
  if (!r) return;
  ownRecords = ownRecords.filter(x => x.id !== id);
  trashItems.unshift({ ...r, _type: 'own' });
  saveOwn();
  saveTrash();
  renderOwnAccounts();
  renderOwnTable();
}

function resetOwnForm() {
  document.getElementById('ownAmount').value = '';
  document.getElementById('ownReason').value = '';
  const now = new Date();
  document.getElementById('ownDate').value = now.toISOString().split('T')[0];
  document.getElementById('ownTime').value = now.toTimeString().slice(0, 5);
}

/* ============================================================
   MY ACCOUNT SEARCH — searches only within "My Account" names
   ============================================================ */
function initOwnSearch() {
  const toggleBtn = document.getElementById('ownSearchToggleBtn');
  const box       = document.getElementById('ownSearchBox');
  const input     = document.getElementById('ownSearchInput');
  const results   = document.getElementById('ownSearchResults');
  const wrap      = document.getElementById('ownSearchWrap');

  toggleBtn.addEventListener('click', () => {
    const isHidden = box.style.display === 'none';
    box.style.display = isHidden ? 'block' : 'none';
    if (isHidden) {
      input.value = '';
      results.innerHTML = '';
      input.focus();
    }
  });

  input.addEventListener('input', () => {
    const q = input.value.trim().toLowerCase();
    if (!q) { results.innerHTML = ''; return; }

    const matches = getOwnGroups().filter(g => g.name.toLowerCase().includes(q));

    if (matches.length === 0) {
      results.innerHTML = '<div class="search-empty">No matching account found.</div>';
      return;
    }

    results.innerHTML = matches.map(g => `
      <div class="search-result-item" onclick="selectOwnSearchResult('${escAttr(g.name)}')">
        <span class="search-result-name">${esc(g.name)}</span>
        <span class="search-result-total">Rs. ${g.total.toLocaleString('en-PK')}</span>
      </div>
    `).join('');
  });

  document.addEventListener('click', (e) => {
    if (!wrap.contains(e.target)) box.style.display = 'none';
  });

  input.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') box.style.display = 'none';
  });
}

function selectOwnSearchResult(name) {
  document.getElementById('ownSearchBox').style.display = 'none';
  filterByOwnPerson(name);
}

/* ---- Grouped by the person the money was borrowed from ---- */
function getOwnGroups() {
  const groups = {};
  ownRecords.forEach(r => {
    const key = r.from.trim().toLowerCase();
    if (!groups[key]) groups[key] = { name: r.from.trim(), total: 0, count: 0 };
    if (!r.struck) groups[key].total += r.amount;
    groups[key].count += 1;
  });
  // Keep insertion order (newest entry first) instead of sorting by total.
  return Object.values(groups);
}

function renderOwnAccounts() {
  renderDashboard();
  const area  = document.getElementById('ownAccountsArea');
  const badge = document.getElementById('ownStudentCountBadge');
  const groups = getOwnGroups();

  badge.textContent = groups.length + ' People';

  if (groups.length === 0) {
    area.innerHTML = '<div class="empty-state">You have not added anyone yet.</div>';
    return;
  }

  let html = '<div class="student-grid">';
  groups.forEach(g => {
    const isActive = ownCurrentFilter && ownCurrentFilter.toLowerCase() === g.name.toLowerCase();
    html += `<div class="student-account-card${isActive ? ' active' : ''}">
      <div class="student-account-name">${esc(g.name)}</div>
      <div class="student-account-meta">${g.count} ${g.count === 1 ? 'entry' : 'entries'}</div>
      <div class="student-account-total">Rs. ${g.total.toLocaleString('en-PK')}</div>
      <div class="student-account-actions">
        <button class="btn-view" onclick="filterByOwnPerson('${escAttr(g.name)}')">View List</button>
        <button class="btn-student-download" onclick="downloadOwnPersonPDF('${escAttr(g.name)}')">Download</button>
      </div>
    </div>`;
  });
  html += '</div>';
  area.innerHTML = html;
}

function filterByOwnPerson(name) {
  ownCurrentFilter = name;
  renderOwnAccounts();
  renderOwnTable();
  document.getElementById('ownTableArea').scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

function clearOwnFilter() {
  ownCurrentFilter = null;
  renderOwnAccounts();
  renderOwnTable();
}

function renderOwnTable() {
  const area     = document.getElementById('ownTableArea');
  const badge    = document.getElementById('ownCountBadge');
  const bar      = document.getElementById('ownTotalBar');
  const dlBtn    = document.getElementById('ownDownloadAllBtn');
  const clearBtn = document.getElementById('ownClearFilterBtn');
  const titleEl  = document.getElementById('ownRecordsTitle');
  const totalLabelEl = document.getElementById('ownTotalLabel');

  const visible = ownCurrentFilter
    ? ownRecords.filter(r => r.from.trim().toLowerCase() === ownCurrentFilter.toLowerCase())
    : ownRecords;

  if (ownCurrentFilter) {
    titleEl.textContent = 'Repaid ' + ownCurrentFilter;
    totalLabelEl.textContent = 'Total Owed to ' + ownCurrentFilter;
    if (clearBtn) clearBtn.style.display = 'inline-block';
    dlBtn.textContent = 'Download ' + ownCurrentFilter + "'s Receipt";
    dlBtn.onclick = () => downloadOwnPersonPDF(ownCurrentFilter);
  } else {
    titleEl.textContent = 'My Loan History';
    totalLabelEl.textContent = 'Total Borrowed';
    if (clearBtn) clearBtn.style.display = 'none';
    dlBtn.textContent = 'Download All Receipt';
    dlBtn.onclick = () => downloadOwnAllPDF();
  }

  badge.textContent = visible.length + ' Records';

  if (visible.length === 0) {
    area.innerHTML = '<div class="empty-state">No records added yet.</div>';
    bar.style.display = 'none';
    dlBtn.style.display = 'none';
    return;
  }

  const total = visible.reduce((s, r) => s + (r.struck ? 0 : r.amount), 0);
  document.getElementById('ownTotalAmount').textContent = 'Rs. ' + total.toLocaleString('en-PK');
  bar.style.display = 'flex';
  dlBtn.style.display = 'inline-block';

  let rows = '';
  visible.forEach((r, i) => {
    const serial = visible.length - i;
    rows += `<tr>
      <td class="td-muted">${serial}</td>
      <td class="td-bold">${esc(r.from)}</td>
      <td class="td-amount${r.struck ? ' struck-amount' : ''}">Rs. ${r.amount.toLocaleString('en-PK')}</td>
      <td class="td-reason" title="${esc(r.reason)}" onclick="this.classList.toggle('reason-expanded')">${esc(r.reason)}</td>
      <td class="td-muted" style="white-space:nowrap;">${r.date} &nbsp; ${r.time}</td>
      <td class="td-check"><input type="checkbox" class="strike-check" ${r.struck ? 'checked' : ''} onchange="toggleOwnStrike(${r.id})" title="Mark as settled"/></td>
      <td><button class="btn-del" onclick="deleteOwnRecord(${r.id})">Delete</button></td>
    </tr>`;
  });

  area.innerHTML = `<div class="table-wrap"><table>
    <thead><tr>
      <th>#</th><th>Repaid</th><th class="th-blue">Amount</th><th>Reason</th><th>Date / Time</th><th>Paid</th><th></th>
    </tr></thead>
    <tbody>${rows}</tbody>
  </table></div>`;
}

function toggleOwnStrike(id) {
  const r = ownRecords.find(x => x.id === id);
  if (!r) return;
  r.struck = !r.struck;
  saveOwn();
  renderOwnTable();
  renderOwnAccounts();
}

/* ---- PDF for own borrowed money ---- */
function downloadOwnAllPDF() {
  const list = ownCurrentFilter
    ? ownRecords.filter(r => r.from.trim().toLowerCase() === ownCurrentFilter.toLowerCase())
    : ownRecords;
  const title = ownCurrentFilter ? 'Payment Return to ' + ownCurrentFilter : 'My Loans Receipt';
  const filePrefix = ownCurrentFilter ? ownCurrentFilter.replace(/\s+/g, '_') + '_Owed_Receipt' : 'My_Loans_Receipt';
  buildOwnPDF(list, title, filePrefix);
}

function downloadOwnPersonPDF(personName) {
  const list = ownRecords.filter(r => r.from.trim().toLowerCase() === personName.toLowerCase());
  if (list.length === 0) return;
  const title = 'Payment Return to ' + personName;
  const filePrefix = personName.replace(/\s+/g, '_') + '_Owed_Receipt';
  buildOwnPDF(list, title, filePrefix);
}

function buildOwnPDF(recordsList, titleText, filenamePrefix, opts) {
  if (recordsList.length === 0) return;
  const noAmount = !!(opts && opts.noAmount);   // 'Item Return' receipts: no Amount column, no Total Loan

  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit: 'mm', format: 'a4' });
  const W      = doc.internal.pageSize.getWidth();
  const H      = doc.internal.pageSize.getHeight();
  const margin = 14;
  const today  = new Date().toLocaleDateString('en-PK');
  const total  = recordsList.reduce((s, r) => s + (r.struck ? 0 : (r.amount || 0)), 0);

  // Columns: #, Repayment, Amount, Date/Time, Reason  (Item Return: no Amount column)
  const cols = noAmount ? [
    { x: margin,       w: 10 },
    { x: margin + 10,  w: 56 },
    { x: margin + 66,  w: 30 },
    { x: margin + 96,  w: W - margin - 96 - margin }
  ] : [
    { x: margin,       w: 10 },
    { x: margin + 10,  w: 46 },
    { x: margin + 56,  w: 30 },
    { x: margin + 86,  w: 30 },
    { x: margin + 116, w: W - margin - 116 - margin }
  ];
  const repayLabel = (opts && opts.repayLabel) || 'Repayment';
  const reasonLabel = (opts && opts.reasonLabel) || 'Reason';
  const headers = noAmount ? ['No.', repayLabel, 'Date / Time', reasonLabel] : ['No.', repayLabel, 'Amount', 'Date / Time', reasonLabel];
  const dateCol = noAmount ? 2 : 3;
  const reasonCol = noAmount ? 3 : 4;

  function pageHeader(isFirst) {
    drawReceiptHeader(doc, W, isFirst, titleText, today);
  }

  pageHeader(true);

  doc.setFillColor(255, 245, 245);
  doc.setDrawColor(200, 180, 180);
  doc.setLineWidth(0.4);
  doc.roundedRect(margin, 38, W - margin * 2, 12, 2, 2, 'FD');
  doc.setTextColor(80, 80, 80);
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(8);
  doc.text('Total Records: ' + recordsList.length, margin + 4, 46);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(0, 110, 182);
  doc.setFontSize(9);
  if (!noAmount) doc.text('Total Loan: Rs. ' + total.toLocaleString('en-PK'), W - margin - 4, 46, { align: 'right' });

  let y = 57;

  function drawTableHeader() {
    doc.setFillColor(235, 235, 235);
    doc.rect(margin, y, W - margin * 2, 8, 'F');
    doc.setDrawColor(170, 170, 170);
    doc.setLineWidth(0.3);
    doc.rect(margin, y, W - margin * 2, 8, 'S');
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(7.5);
    doc.setTextColor(60, 60, 60);
    headers.forEach((h, i) => doc.text(h, cols[i].x + 2, y + 5.5));
    y += 10;
  }

  drawTableHeader();

  const orderedRecords = [...recordsList].reverse();
  orderedRecords.forEach((r, idx) => {
    doc.setFontSize(7.5);
    const reasonLines = wrapMultiline(doc, r.reason, cols[reasonCol].w - 4);
    const rowH = Math.max(9, reasonLines.length * 4.5 + 3);

    if (y + rowH > H - 30) {
      drawPageFooter();
      doc.addPage();
      pageHeader(false);
      y = 38;
      drawTableHeader();
    }

    const bg = idx % 2 === 0 ? [255, 255, 255] : [249, 249, 249];
    doc.setFillColor(...bg);
    doc.rect(margin, y, W - margin * 2, rowH, 'F');
    doc.setDrawColor(215, 215, 215);
    doc.setLineWidth(0.2);
    doc.line(margin, y + rowH, W - margin, y + rowH);

    const midY = y + rowH / 2 + 1.5;

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(7.5);
    doc.setTextColor(130, 130, 130);
    doc.text(String(idx + 1), cols[0].x + 2, midY);

    doc.setFont('helvetica', 'bold');
    doc.setFontSize(10);
    doc.setTextColor(26, 26, 26);
    doc.text(doc.splitTextToSize(r.from, cols[1].w - 4), cols[1].x + 2, midY);

    if (!noAmount) {
      doc.setFont('helvetica', r.struck ? 'italic' : 'bold');
      doc.setFontSize(8);
      doc.setTextColor(0, 110, 182);
      const amountText = 'Rs. ' + r.amount.toLocaleString('en-PK');
      doc.text(amountText, cols[2].x + 2, midY);
      if (r.struck) {
        const tw = doc.getTextWidth(amountText);
        doc.setDrawColor(0, 0, 0);
        doc.setLineWidth(0.35);
        doc.line(cols[2].x + 2, midY - 1.3, cols[2].x + 2 + tw, midY - 1.3);
      }
    }

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(7);
    doc.setTextColor(100, 100, 100);
    doc.text(r.date, cols[dateCol].x + 2, y + rowH / 2 - 0.5);
    doc.text(r.time, cols[dateCol].x + 2, y + rowH / 2 + 4);

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(9);
    doc.setTextColor(26, 26, 26);
    const reasonTopY = y + (rowH - reasonLines.length * 4.5) / 2 + 3;
    doc.text(reasonLines, cols[reasonCol].x + 2, reasonTopY);

    y += rowH;
  });

  drawPageFooter();
  trackEvent('file_download', { file_extension: 'pdf', section: 'main' });
  offerReceiptDownload(doc, filenamePrefix + '_' + today.replace(/\//g, '-'));

  function drawPageFooter() {
    doc.setTextColor(120, 130, 150);
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(7);
    doc.text('Copyright © 2026 FM Register — ' + today, W / 2, H - 9.8, { align: 'center' });
  }
}
/* ============================================================
   ADVANCE ACCOUNTS — money given to people that they still owe
   back (kept in a separate Firestore field from the main and
   own records, mirroring the same pattern)
   ============================================================ */
/* Amount Taken / Amount Price / Amount Remaining auto-calculation:
   Price + Remaining = Taken. Typing in one of Price / Remaining fills the other. */
let advanceLastEdited = null; // 'price' | 'remaining'
function advRound(n) { return Math.round(n * 100) / 100; }
function advGetPrice(r) {
  if (typeof r.amountPrice === 'number') return r.amountPrice;
  return advRound((r.amountTaken || 0) - (r.amountRemaining || 0)); // older records
}
function initAdvanceAutoCalc() {
  const takenEl = document.getElementById('advanceAmountTaken');
  const priceEl = document.getElementById('advanceAmountPrice');
  const remEl   = document.getElementById('advanceAmountRemaining');
  if (!takenEl || !priceEl || !remEl) return;

  function fromPrice() {
    const t = parseFloat(takenEl.value), p = parseFloat(priceEl.value);
    remEl.value = (isNaN(t) || isNaN(p)) ? '' : advRound(t - p);
  }
  function fromRemaining() {
    const t = parseFloat(takenEl.value), r = parseFloat(remEl.value);
    priceEl.value = (isNaN(t) || isNaN(r)) ? '' : advRound(t - r);
  }
  priceEl.addEventListener('input', () => { advanceLastEdited = 'price'; fromPrice(); });
  remEl.addEventListener('input',   () => { advanceLastEdited = 'remaining'; fromRemaining(); });
  takenEl.addEventListener('input', () => {
    if (advanceLastEdited === 'price') fromPrice();
    else if (advanceLastEdited === 'remaining') fromRemaining();
  });
}

function addAdvanceRecord() {
  const name            = document.getElementById('advanceName').value.trim();
  const otherName       = document.getElementById('advanceOtherName').value.trim();
  const amountTaken     = parseFloat(document.getElementById('advanceAmountTaken').value);
  const amountPriceRaw  = document.getElementById('advanceAmountPrice').value;
  const amountPrice     = amountPriceRaw === '' ? NaN : parseFloat(amountPriceRaw);
  const amountRemainingRaw = document.getElementById('advanceAmountRemaining').value;
  let amountRemaining   = amountRemainingRaw === '' ? NaN : parseFloat(amountRemainingRaw);
  const date    = document.getElementById('advanceDate').value;
  const timeRaw = document.getElementById('advanceTime').value;
  const time    = convertTo12hr(timeRaw);
  const reason  = document.getElementById('advanceReason').value.trim();

  if (!name)      { alert('Plz enter the name.'); return; }
  if (!otherName) { alert('Plz enter the other name.'); return; }
  if (!amountTaken || amountTaken <= 0) { alert('Plz enter a valid amount taken.'); return; }
  if (isNaN(amountPrice) && isNaN(amountRemaining)) { alert('Plz enter the amount price.'); return; }
  let price = amountPrice;
  if (isNaN(price)) price = advRound(amountTaken - amountRemaining);
  if (isNaN(amountRemaining)) amountRemaining = advRound(amountTaken - price);
  if (price < 0 || amountRemaining < 0) { alert('Amount Price cannot be more than Amount Taken.'); return; }
  if (!date)     { alert('Plz select a date.'); return; }
  if (!timeRaw)  { alert('Plz select a time.'); return; }
  if (!reason)   { alert('Plz enter a reason.'); return; }

  advanceRecords.unshift({ id: Date.now(), name, otherName, amountTaken, amountPrice: price, amountRemaining, date, time, reason });
  trackEvent('add_entry', { section: 'tasks' });
  saveAdvance();
  renderAdvanceAccounts();
  renderAdvanceTable();
  resetAdvanceForm();
  showToast();
}

function saveAdvance() {
  if (!currentAccountKey) return;
  accountDocRef(currentAccountKey).set({ myAdvanceDebt: advanceRecords }, { merge: true })
    .catch(err => console.error('Save failed:', err));
}

function deleteAdvanceRecord(id) {
  if (!confirm('Move this record to Trash?')) return;
  const r = advanceRecords.find(x => x.id === id);
  if (!r) return;
  advanceRecords = advanceRecords.filter(x => x.id !== id);
  trashItems.unshift({ ...r, _type: 'advance' });
  saveAdvance();
  saveTrash();
  renderAdvanceAccounts();
  renderAdvanceTable();
}

function resetAdvanceForm() {
  document.getElementById('advanceAmountTaken').value = '';
  document.getElementById('advanceAmountPrice').value = '';
  document.getElementById('advanceAmountRemaining').value = '';
  advanceLastEdited = null;
  document.getElementById('advanceReason').value = '';
  const now = new Date();
  document.getElementById('advanceDate').value = now.toISOString().split('T')[0];
  document.getElementById('advanceTime').value = now.toTimeString().slice(0, 5);
}

/* ============================================================
   ADVANCE SEARCH — searches only within "Tasks" names
   ============================================================ */
function initAdvanceSearch() {
  const toggleBtn = document.getElementById('advanceSearchToggleBtn');
  const box       = document.getElementById('advanceSearchBox');
  const input     = document.getElementById('advanceSearchInput');
  const results   = document.getElementById('advanceSearchResults');
  const wrap      = document.getElementById('advanceSearchWrap');

  toggleBtn.addEventListener('click', () => {
    const isHidden = box.style.display === 'none';
    box.style.display = isHidden ? 'block' : 'none';
    if (isHidden) {
      input.value = '';
      results.innerHTML = '';
      input.focus();
    }
  });

  input.addEventListener('input', () => {
    const q = input.value.trim().toLowerCase();
    if (!q) { results.innerHTML = ''; return; }

    const matches = getAdvanceGroups().filter(g => g.name.toLowerCase().includes(q));

    if (matches.length === 0) {
      results.innerHTML = '<div class="search-empty">No matching account found.</div>';
      return;
    }

    results.innerHTML = matches.map(g => `
      <div class="search-result-item" onclick="selectAdvanceSearchResult('${escAttr(g.name)}')">
        <span class="search-result-name">${esc(g.name)}</span>
        <span class="search-result-total">Rs. ${g.total.toLocaleString('en-PK')}</span>
      </div>
    `).join('');
  });

  document.addEventListener('click', (e) => {
    if (!wrap.contains(e.target)) box.style.display = 'none';
  });

  input.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') box.style.display = 'none';
  });
}

function selectAdvanceSearchResult(name) {
  document.getElementById('advanceSearchBox').style.display = 'none';
  filterByAdvancePerson(name);
}

/* ---- Grouped by the Other Name field ---- */
function getAdvanceGroups() {
  const groups = {};
  advanceRecords.forEach(r => {
    const key = r.otherName.trim().toLowerCase();
    if (!groups[key]) groups[key] = { name: r.otherName.trim(), total: 0, count: 0 };
    if (!r.struck) groups[key].total += r.amountRemaining;
    groups[key].count += 1;
  });
  // Keep insertion order (newest entry first) instead of sorting by total.
  return Object.values(groups);
}

function renderAdvanceAccounts() {
  renderDashboard();
  const area  = document.getElementById('advanceAccountsArea');
  const badge = document.getElementById('advanceStudentCountBadge');
  const groups = getAdvanceGroups();

  badge.textContent = groups.length + ' Tasks';

  if (groups.length === 0) {
    area.innerHTML = '<div class="empty-state">No tasks yet.</div>';
    return;
  }

  let html = '<div class="student-grid">';
  groups.forEach(g => {
    const isActive = advanceCurrentFilter && advanceCurrentFilter.toLowerCase() === g.name.toLowerCase();
    html += `<div class="student-account-card${isActive ? ' active' : ''}">
      <div class="student-account-name">${esc(g.name)}</div>
      <div class="student-account-meta">${g.count} ${g.count === 1 ? 'entry' : 'entries'}</div>
      <div class="student-account-total">Rs. ${g.total.toLocaleString('en-PK')}</div>
      <div class="student-account-actions">
        <button class="btn-view" onclick="filterByAdvancePerson('${escAttr(g.name)}')">View List</button>
        <button class="btn-student-download" onclick="downloadAdvancePersonPDF('${escAttr(g.name)}')">Download</button>
      </div>
    </div>`;
  });
  html += '</div>';
  area.innerHTML = html;
}

function filterByAdvancePerson(name) {
  advanceCurrentFilter = name;
  renderAdvanceAccounts();
  renderAdvanceTable();
  document.getElementById('advanceTableArea').scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

function clearAdvanceFilter() {
  advanceCurrentFilter = null;
  renderAdvanceAccounts();
  renderAdvanceTable();
}

function renderAdvanceTable() {
  const area     = document.getElementById('advanceTableArea');
  const badge    = document.getElementById('advanceCountBadge');
  const bar      = document.getElementById('advanceTotalBar');
  const dlBtn    = document.getElementById('advanceDownloadAllBtn');
  const clearBtn = document.getElementById('advanceClearFilterBtn');
  const titleEl  = document.getElementById('advanceRecordsTitle');
  const totalLabelEl = document.getElementById('advanceTotalLabel');

  const visible = advanceCurrentFilter
    ? advanceRecords.filter(r => r.otherName.trim().toLowerCase() === advanceCurrentFilter.toLowerCase())
    : advanceRecords;

  if (advanceCurrentFilter) {
    titleEl.textContent = advanceCurrentFilter + "'s Task Records";
    totalLabelEl.textContent = advanceCurrentFilter + "'s Total Remaining";
    if (clearBtn) clearBtn.style.display = 'inline-block';
    dlBtn.textContent = 'Download ' + advanceCurrentFilter + "'s Receipt";
    dlBtn.onclick = () => downloadAdvancePersonPDF(advanceCurrentFilter);
  } else {
    titleEl.textContent = 'Task History';
    totalLabelEl.textContent = 'Total Remaining';
    if (clearBtn) clearBtn.style.display = 'none';
    dlBtn.textContent = 'Download All Receipt';
    dlBtn.onclick = () => downloadAdvanceAllPDF();
  }

  badge.textContent = visible.length + ' Records';

  if (visible.length === 0) {
    area.innerHTML = '<div class="empty-state">No records added yet.</div>';
    bar.style.display = 'none';
    dlBtn.style.display = 'none';
    return;
  }

  const total = visible.reduce((s, r) => s + (r.struck ? 0 : r.amountRemaining), 0);
  document.getElementById('advanceTotalAmount').textContent = 'Rs. ' + total.toLocaleString('en-PK');
  bar.style.display = 'flex';
  dlBtn.style.display = 'inline-block';

  let rows = '';
  visible.forEach((r, i) => {
    const serial = visible.length - i;
    rows += `<tr>
      <td class="td-muted">${serial}</td>
      <td class="td-bold">${esc(r.name)}</td>
      <td>${esc(r.otherName)}</td>
      <td class="td-amount td-amount-taken${r.struck ? ' struck-amount' : ''}">Rs. ${r.amountTaken.toLocaleString('en-PK')}</td>
      <td class="td-amount td-amount-price${r.struck ? ' struck-amount' : ''}">Rs. ${advGetPrice(r).toLocaleString('en-PK')}</td>
      <td class="td-amount${r.struck ? ' struck-amount' : ''}">Rs. ${r.amountRemaining.toLocaleString('en-PK')}</td>
      <td class="td-reason" title="${esc(r.reason)}" onclick="this.classList.toggle('reason-expanded')">${esc(r.reason)}</td>
      <td class="td-muted" style="white-space:nowrap;">${r.date} &nbsp; ${r.time}</td>
      <td class="td-check"><input type="checkbox" class="strike-check" ${r.struck ? 'checked' : ''} onchange="toggleAdvanceStrike(${r.id})" title="Mark as settled"/></td>
      <td><button class="btn-del" onclick="deleteAdvanceRecord(${r.id})">Delete</button></td>
    </tr>`;
  });

  area.innerHTML = `<div class="table-wrap"><table>
    <thead><tr>
      <th>#</th><th>Name</th><th>Other Name</th><th>Amount Taken</th><th>Amount Price</th><th>Amount Remaining</th><th>Reason</th><th>Date / Time</th><th>Paid</th><th></th>
    </tr></thead>
    <tbody>${rows}</tbody>
  </table></div>`;
}

function toggleAdvanceStrike(id) {
  const r = advanceRecords.find(x => x.id === id);
  if (!r) return;
  r.struck = !r.struck;
  saveAdvance();
  renderAdvanceTable();
  renderAdvanceAccounts();
}

/* ---- PDF for advance accounts ---- */
function downloadAdvanceAllPDF() {
  const list = advanceCurrentFilter
    ? advanceRecords.filter(r => r.otherName.trim().toLowerCase() === advanceCurrentFilter.toLowerCase())
    : advanceRecords;
  const title = advanceCurrentFilter ? advanceCurrentFilter + "'s Task Receipt" : 'Tasks Receipt';
  const filePrefix = advanceCurrentFilter ? advanceCurrentFilter.replace(/\s+/g, '_') + '_Task_Receipt' : 'Task_Receipt_list_FM';
  buildAdvancePDF(list, title, filePrefix);
}

function downloadAdvancePersonPDF(personName) {
  const list = advanceRecords.filter(r => r.otherName.trim().toLowerCase() === personName.toLowerCase());
  if (list.length === 0) return;
  const title = personName + "'s Task Receipt";
  const filePrefix = personName.replace(/\s+/g, '_') + '_Task_Receipt';
  buildAdvancePDF(list, title, filePrefix);
}

function buildAdvancePDF(recordsList, titleText, filenamePrefix) {
  if (recordsList.length === 0) return;

  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit: 'mm', format: 'a4' });
  const W      = doc.internal.pageSize.getWidth();
  const H      = doc.internal.pageSize.getHeight();
  const margin = 14;
  const today  = new Date().toLocaleDateString('en-PK');
  const total  = recordsList.reduce((s, r) => s + (r.struck ? 0 : r.amountRemaining), 0);

  // Columns: #, Name, Other Name, Taken, Price, Remaining, Date/Time, Reason
  const cols = [
    { x: margin,       w: 7  },
    { x: margin + 7,   w: 24 },
    { x: margin + 31,  w: 24 },
    { x: margin + 55,  w: 21 },
    { x: margin + 76,  w: 21 },
    { x: margin + 97,  w: 23 },
    { x: margin + 120, w: 24 },
    { x: margin + 144, w: W - margin - 144 - margin }
  ];
  const headers = ['No.', 'Name', 'Other Name', 'Taken', 'Price', 'Remaining', 'Date / Time', 'Reason'];

  function pageHeader(isFirst) {
    drawReceiptHeader(doc, W, isFirst, titleText, today);
  }

  pageHeader(true);

  doc.setFillColor(255, 245, 245);
  doc.setDrawColor(200, 180, 180);
  doc.setLineWidth(0.4);
  doc.roundedRect(margin, 38, W - margin * 2, 12, 2, 2, 'FD');
  doc.setTextColor(80, 80, 80);
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(8);
  doc.text('Total Records: ' + recordsList.length, margin + 4, 46);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(0, 110, 182);
  doc.setFontSize(9);
  doc.text('Total Remaining: Rs. ' + total.toLocaleString('en-PK'), W - margin - 4, 46, { align: 'right' });

  let y = 57;

  function drawTableHeader() {
    doc.setFillColor(235, 235, 235);
    doc.rect(margin, y, W - margin * 2, 8, 'F');
    doc.setDrawColor(170, 170, 170);
    doc.setLineWidth(0.3);
    doc.rect(margin, y, W - margin * 2, 8, 'S');
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(7.5);
    doc.setTextColor(60, 60, 60);
    headers.forEach((h, i) => doc.text(h, cols[i].x + 2, y + 5.5));
    y += 10;
  }

  drawTableHeader();

  const orderedRecords = [...recordsList].reverse();
  orderedRecords.forEach((r, idx) => {
    doc.setFontSize(7.5);
    const reasonLines = wrapMultiline(doc, r.reason, cols[7].w - 4);
    const rowH = Math.max(9, reasonLines.length * 4.5 + 3);

    if (y + rowH > H - 30) {
      drawPageFooter();
      doc.addPage();
      pageHeader(false);
      y = 38;
      drawTableHeader();
    }

    const bg = idx % 2 === 0 ? [255, 255, 255] : [249, 249, 249];
    doc.setFillColor(...bg);
    doc.rect(margin, y, W - margin * 2, rowH, 'F');
    doc.setDrawColor(215, 215, 215);
    doc.setLineWidth(0.2);
    doc.line(margin, y + rowH, W - margin, y + rowH);

    const midY = y + rowH / 2 + 1.5;

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(7.5);
    doc.setTextColor(130, 130, 130);
    doc.text(String(idx + 1), cols[0].x + 2, midY);

    doc.setFont('helvetica', 'bold');
    doc.setFontSize(9);
    doc.setTextColor(26, 26, 26);
    doc.text(doc.splitTextToSize(r.name, cols[1].w - 4), cols[1].x + 2, midY);

    doc.setFont('helvetica', 'bold');
    doc.setFontSize(9);
    doc.setTextColor(50, 50, 50);
    doc.text(doc.splitTextToSize(r.otherName, cols[2].w - 4), cols[2].x + 2, midY);

    doc.setFont('helvetica', r.struck ? 'italic' : 'bold');
    doc.setFontSize(7.5);
    doc.setTextColor(139, 38, 38);
    const takenText = 'Rs. ' + r.amountTaken.toLocaleString('en-PK');
    doc.text(takenText, cols[3].x + 2, midY);
    if (r.struck) {
      const tw = doc.getTextWidth(takenText);
      doc.setDrawColor(0, 0, 0);
      doc.setLineWidth(0.35);
      doc.line(cols[3].x + 2, midY - 1.3, cols[3].x + 2 + tw, midY - 1.3);
    }

    doc.setFont('helvetica', r.struck ? 'italic' : 'bold');
    doc.setFontSize(7.5);
    doc.setTextColor(22, 128, 60);
    const priceText = 'Rs. ' + advGetPrice(r).toLocaleString('en-PK');
    doc.text(priceText, cols[4].x + 2, midY);
    if (r.struck) {
      const pw = doc.getTextWidth(priceText);
      doc.setDrawColor(0, 0, 0);
      doc.setLineWidth(0.35);
      doc.line(cols[4].x + 2, midY - 1.3, cols[4].x + 2 + pw, midY - 1.3);
    }

    doc.setFont('helvetica', r.struck ? 'italic' : 'normal');
    doc.setFontSize(7.5);
    doc.setTextColor(0, 110, 182);
    const remainingText = 'Rs. ' + r.amountRemaining.toLocaleString('en-PK');
    doc.text(remainingText, cols[5].x + 2, midY);
    if (r.struck) {
      const rw = doc.getTextWidth(remainingText);
      doc.setDrawColor(0, 0, 0);
      doc.setLineWidth(0.35);
      doc.line(cols[5].x + 2, midY - 1.3, cols[5].x + 2 + rw, midY - 1.3);
    }

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(7);
    doc.setTextColor(100, 100, 100);
    doc.text(r.date, cols[6].x + 2, y + rowH / 2 - 0.5);
    doc.text(r.time, cols[6].x + 2, y + rowH / 2 + 4);

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(9);
    doc.setTextColor(26, 26, 26);
    const reasonTopY = y + (rowH - reasonLines.length * 4.5) / 2 + 3;
    doc.text(reasonLines, cols[7].x + 2, reasonTopY);

    y += rowH;
  });

  drawPageFooter();
  trackEvent('file_download', { file_extension: 'pdf', section: 'tasks' });
  offerReceiptDownload(doc, filenamePrefix + '_' + today.replace(/\//g, '-'));

  function drawPageFooter() {
    doc.setTextColor(120, 130, 150);
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(7);
    doc.text('Copyright © 2026 FM Register — ' + today, W / 2, H - 9.8, { align: 'center' });
  }
}

